import { createStudio } from './studio.js';
import { createSampleCanvas, SAMPLE_COLLECTIONS } from './sample.js';
import { initFeatures } from './features.js';
import { initNeural } from './neural.js';
import { exportCuttingSVG, exportPlanJSON } from './vision.js';
import { initLab } from './lab.js';
import { createHero } from './hero.js';
const $=id=>document.getElementById(id);
const state={photo:null,analysis:null,plan:null,product:'tote',objective:'color',size:1,rotation:true,excluded:new Set(),seam:.7,grainAware:true,outlines:true,selected:null,filename:'sample · earth tones',sample:true,variant:'earth',busy:false,view:'studio',generation:0,replanQueued:false};
let toastTimer, requestId=0, lab=null, hero=null;const pending=new Map();const thumbs=new WeakMap();
const PATTERN_TAGS={solid:'Solid',textured:'Textured',stripe:'Stripe',check:'Check',dot:'Dots',print:'Print'};
function scrapThumb(s){if(thumbs.has(s))return thumbs.get(s);const c=document.createElement('canvas');c.width=c.height=72;const b=s.bbox,side=Math.min(b.width,b.height)*.62;try{c.getContext('2d').drawImage(state.photo,b.x+b.width/2-side/2,b.y+b.height/2-side/2,side,side,0,0,72,72);}catch{}const url=c.toDataURL('image/jpeg',.8);thumbs.set(s,url);return url;}
const worker=new Worker('./vision-worker.js',{type:'module'});
worker.onmessage=({data})=>{const callbacks=pending.get(data.requestId);if(!callbacks)return;pending.delete(data.requestId);data.error?callbacks.reject(new Error(data.error)):callbacks.resolve(data);};
worker.onerror=()=>{pending.forEach(p=>p.reject(new Error('The image engine could not load. Refresh and try again.')));pending.clear();};
function compute(type,extra={}){return new Promise((resolve,reject)=>{const id=++requestId;pending.set(id,{resolve,reject});const options={product:state.product,seamAllowanceCm:state.seam,rotation:state.rotation,size:state.size,objective:state.objective,grainAware:state.grainAware};const message={requestId:id,type,options,excludedIds:[...state.excluded],...extra};if(type==='analyze'){message.imageData=state.photo.getContext('2d').getImageData(0,0,state.photo.width,state.photo.height);message.sceneWidthCm=Number($('scene-width').value);}worker.postMessage(message);});}
const studio=createStudio($('three-container'),{onReady:result=>{if(result?.supported===false){document.querySelector('.live-badge').textContent='3D UNAVAILABLE';}},onAssembly:active=>{$('preview-card').classList.toggle('assembling',active);$('assembly-chip').hidden=!active;if(active&&state.plan)$('assembly-chip').innerHTML=`<span></span> CUTTING ${state.plan.pieces.length} PIECES FROM YOUR PHOTO`;}});
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500);}
function icon(name){return `<svg><use href="#i-${name}"/></svg>`;}
function escape(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function modal(title,content,eyebrow='BEHIND THE SEAMS'){$('dialog-eyebrow').textContent=eyebrow;$('dialog-content').innerHTML=`<h2>${title}</h2>${content}`;if(!$('info-dialog').open)$('info-dialog').showModal();}
$('close-dialog').onclick=()=>$('info-dialog').close();$('info-dialog').addEventListener('click',event=>{const r=$('info-dialog').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('info-dialog').close();});
function renderSource(){if(!state.photo)return;const canvas=$('source-canvas');canvas.width=state.photo.width;canvas.height=state.photo.height;const ctx=canvas.getContext('2d');ctx.drawImage(state.photo,0,0);if(!state.outlines||!state.analysis)return;const scale=canvas.width/1200;state.analysis.scraps.forEach((scrap,i)=>{ctx.save();ctx.beginPath();scrap.contour.forEach((p,j)=>j?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=state.selected===scrap.id?'#d3edac40':'#ffffff05';ctx.fill();ctx.strokeStyle=state.selected===scrap.id?'#294b2d':'#fafee6d9';ctx.lineWidth=(state.selected===scrap.id?3:2)*scale;ctx.setLineDash([8*scale,5*scale]);ctx.stroke();ctx.setLineDash([]);const x=scrap.bbox.x+scrap.bbox.width*.5,y=scrap.bbox.y+scrap.bbox.height*.5,r=14*scale;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle='#fafcefdb';ctx.fill();ctx.strokeStyle='#81966366';ctx.lineWidth=1*scale;ctx.stroke();ctx.font=`500 ${11*scale}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#657a4a';ctx.fillText(String(i+1).padStart(2,'0'),x,y);ctx.restore();});}
function renderPlan(){if(!state.photo||!state.plan)return;const c=$('plan-canvas');c.width=state.photo.width;c.height=state.photo.height;const ctx=c.getContext('2d');ctx.drawImage(state.photo,0,0);ctx.fillStyle='#ffffef45';ctx.fillRect(0,0,c.width,c.height);const scale=c.width/1200;state.plan.pieces.forEach((piece,i)=>{const {x,y,width,height}=piece;ctx.fillStyle='#d6e7b522';ctx.fillRect(x,y,width,height);ctx.strokeStyle='#34592d';ctx.lineWidth=2*scale;ctx.setLineDash([]);ctx.strokeRect(x,y,width,height);const s=state.plan.seamAllowanceCm*state.analysis.pixelsPerCm;ctx.setLineDash([5*scale,3*scale]);ctx.lineWidth=1*scale;ctx.strokeStyle='#354d27aa';ctx.strokeRect(x+s,y+s,Math.max(0,width-2*s),Math.max(0,height-2*s));ctx.setLineDash([]);ctx.fillStyle='#f8fcedd9';const font=9*scale;ctx.font=`600 ${font}px sans-serif`;const text=piece.id;const tw=Math.min(width,ctx.measureText(text).width+12*scale);ctx.fillRect(x+2*scale,y+2*scale,tw,17*scale);ctx.fillStyle='#38562b';ctx.textAlign='left';ctx.fillText(text,x+7*scale,y+13*scale);});$('plan-piece-label').textContent=`${state.plan.pieces.length} measured cuts`;}
function updateMetrics(){const a=state.analysis,p=state.plan;if(!a||!p)return;const count=a.scraps.length;$('detected-count').textContent=`${count} fabric ${count===1?'piece':'pieces'} detected`;$('material-count').textContent=`${count} MATERIALS`;$('scrap-count').textContent=count;$('plan-count').textContent=p.pieces.length;$('utilization').innerHTML=`${Math.round(p.stats.utilization*100)}<span>%</span>`;$('cut-count').textContent=p.pieces.length;$('area-count').innerHTML=`${Math.round(a.metrics.totalAreaCm2).toLocaleString()}<span>cm²</span>`;$('material-bar').firstElementChild.style.width=`${Math.min(100,p.stats.utilization*100)}%`;$('fit-badge').textContent=p.feasible?'GEOMETRY VALIDATED':'PARTIAL LAYOUT';$('fit-badge').classList.toggle('error',!p.feasible);const remainder=Math.round(p.stats.remainingAreaCm2);$('result-note').textContent=p.feasible?`${p.stats.scrapsUsed} scraps used · ${remainder.toLocaleString()} cm² usable fabric remains. Check fabric, grain and scale before cutting.`:`${p.stats.unplaced} cuts did not fit. Try the pouch, add fabric, or use a smaller seam. The 3D view is a concept preview.`;if(!count)$('result-note').textContent='No usable pieces detected. Try a flat photo with gaps between scraps and a contrasting background.';const titles={tote:'The everyday tote',pouch:'The little pouch',cushion:'The cozy cushion'};$('preview-name').textContent=titles[state.product];$('preview-dimensions').textContent=`${p.dimensions.widthCm} × ${p.dimensions.heightCm} cm · ${p.feasible?'your fabric, reimagined':'concept · incomplete cutting plan'}`;$('product-eyebrow').textContent=p.feasible?'FROM SCRAPS TO STAPLE':'ADD MORE FABRIC TO COMPLETE';const cutsBy=new Map();p.pieces.forEach(x=>cutsBy.set(x.scrapId,(cutsBy.get(x.scrapId)||0)+1));
$('scrap-list').innerHTML=count?a.scraps.map((s,i)=>{const f=s.fabric,g=f?.grain,used=cutsBy.get(s.id)||0;return `<button class="scrap-item${state.selected===s.id?' selected':''}${state.excluded.has(s.id)?' excluded':''}" data-scrap="${escape(s.id)}" title="${escape(s.label)} · ${Math.round(s.areaCm2)} cm²${s.usable?'':' · not cuttable'}${f?.pattern?' · FabricNet: '+escape(PATTERN_TAGS[f.pattern])+' '+Math.round(f.confidence*100)+'%':''}"><span class="swatch" style="background-color:${escape(s.color)};background-image:url(${scrapThumb(s)})">${g?.reliable?`<i class="grain-tick" style="transform:rotate(${g.deviationDeg}deg)"></i>`:''}</span><span class="scrap-name">${escape(s.label.replace(/ \d+$/,''))} ${String(i+1).padStart(2,'0')}</span><span class="scrap-area">${Math.round(s.areaCm2)} cm²${used?` · ${used} cut${used>1?'s':''}`:''}</span>${f?.pattern?`<span class="scrap-tag tag-${escape(f.pattern)}">${escape(PATTERN_TAGS[f.pattern])}${f.directional?' ⇅':''}</span>`:''}</button>`;}).join(''):'<p class="muted">No separated scraps found. Try another photo.</p>';$('scrap-list').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.selected=state.selected===b.dataset.scrap?null:b.dataset.scrap;updateMetrics();renderSource();if(state.selected){const s=a.scraps.find(s=>s.id===state.selected);toast(`${s.label}: ${Math.round(s.areaCm2)} cm² detected · ${Math.round(s.usableAreaCm2)} cm² usable`);}});renderSource();renderPlan();studio.update(p,a.scraps);lab?.onPlan();}
async function analyze(silent=false){if(state.busy||!state.photo)return;const width=Number($('scene-width').value);if(!Number.isFinite(width)||width<10||width>300){toast('Enter the actual photo width between 10 and 300 cm.');$('scene-width').focus();return;}state.busy=true;state.generation++;$('neural-status').textContent='SLIMSAM · SELECT A PIECE FOR NEURAL REVIEW';$('analyze-btn').disabled=true;$('scan-overlay').hidden=false;$('scan-message').textContent='Learning your color palette…';const t=setTimeout(()=>$('scan-message').textContent='Tracing shapes & fitting cutting pieces…',450);try{const result=await compute('analyze');state.analysis=result.analysis;state.plan=result.plan;lab?.onNewPlan();studio.setPhoto(state.photo);updateMetrics();hero?.update(state.analysis,state.photo);studio.playAssembly();if(!silent)toast(state.plan.feasible?'Your materials have a plan. Explore it in 3D.':'Analysis complete. More fabric is needed for this design.');}catch(e){toast(e.message);$('result-note').textContent=e.message;}finally{clearTimeout(t);$('scan-overlay').hidden=true;$('analyze-btn').disabled=false;state.busy=false;if(state.replanQueued){state.replanQueued=false;replan();}}}
async function replan(){if(state.busy){state.replanQueued=true;return;}if(!state.analysis){await analyze();return;}if(state.busy)return;state.busy=true;try{const result=await compute('optimize');state.plan=result.plan;lab?.onNewPlan();updateMetrics();}catch(e){toast(e.message);}finally{state.busy=false;if(state.replanQueued){state.replanQueued=false;replan();}}}
function setPhoto(canvas,{name,sample=false,variant='earth',sceneWidth}={}){state.photo=canvas;state.analysis=null;state.plan=null;state.selected=null;state.excluded=new Set();state.sample=sample;state.variant=variant;state.filename=name||'your fabric photo';$('photo-name').textContent=state.filename;$('photo-tag').innerHTML=`<span></span> ${sample?'ILLUSTRATIVE SAMPLE':'YOUR PHOTO · LOCAL ONLY'}`;$('detected-count').textContent='Ready to analyze';$('material-count').textContent='AWAITING ANALYSIS';$('scrap-count').textContent='—';$('plan-count').textContent='—';$('utilization').innerHTML='—<span>%</span>';$('cut-count').textContent='—';$('area-count').innerHTML='—<span>cm²</span>';$('material-bar').firstElementChild.style.width='0%';$('fit-badge').textContent='READY TO ANALYZE';$('fit-badge').classList.remove('error');$('result-note').textContent='Set the photo width, then analyze to measure usable material.';$('preview-dimensions').textContent='Concept preview · analyze your fabric to create a plan';$('product-eyebrow').textContent='A LITTLE CREATIVE POSSIBILITY';studio.update({product:state.product,pieces:[]},[]);$('scrap-list').innerHTML='<p class="muted">Analyze this photo to build your material library.</p>';if(sceneWidth)$('scene-width').value=sceneWidth;renderSource();studio.setPhoto(canvas);lab?.onNewPlan();}
async function useSample(variant='earth'){const meta=SAMPLE_COLLECTIONS.find(s=>s.id===variant);let canvas;if(meta?.src){const image=new Image();image.src=meta.src;await image.decode();const ratio=Math.min(1,1200/Math.max(image.width,image.height));canvas=document.createElement('canvas');canvas.width=Math.round(image.width*ratio);canvas.height=Math.round(image.height*ratio);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);}else canvas=createSampleCanvas(variant);setPhoto(canvas,{name:meta?.name||`sample · ${variant}`,sample:true,variant,sceneWidth:meta?.sceneWidthCm||canvas.defaultSceneWidthCm||90});if(meta?.generated)$('photo-tag').innerHTML='<span></span> AI-GENERATED SAMPLE';await analyze(true);}
async function loadFile(file){if(!file)return;if(!file.type.startsWith('image/'))return toast('Choose a PNG, JPEG or WebP fabric photo.');if(file.size>25*1024*1024)return toast('Please use a photo smaller than 25 MB.');if(state.busy)return toast('Wait for this analysis to finish.');const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const ratio=Math.min(1,1200/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.round(image.width*ratio);canvas.height=Math.round(image.height*ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#eeece3';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);setPhoto(canvas,{name:file.name,sample:false});toast('Photo loaded. Set its edge-to-edge width, then analyze.');}catch{toast('This photo could not be opened. Try a PNG or JPEG.');}finally{URL.revokeObjectURL(url);}}
$('upload-btn').onclick=()=>$('file-input').click();$('camera-btn').onclick=()=>$('camera-input').click();['file-input','camera-input'].forEach(id=>$(id).onchange=e=>{loadFile(e.target.files[0]);e.target.value='';});$('analyze-btn').onclick=()=>analyze();$('toggle-outlines').onclick=()=>{state.outlines=!state.outlines;$('toggle-outlines').setAttribute('aria-pressed',String(state.outlines));$('toggle-outlines').innerHTML=icon('scan')+(state.outlines?' Detected edges':' Original photo');renderSource();};$('source-canvas').onclick=event=>{if(!state.analysis)return;const r=event.target.getBoundingClientRect(),x=(event.clientX-r.left)/r.width*state.photo.width,y=(event.clientY-r.top)/r.height*state.photo.height;const s=state.analysis.scraps.find(s=>x>=s.bbox.x&&y>=s.bbox.y&&x<s.bbox.x+s.bbox.width&&y<s.bbox.y+s.bbox.height&&s.mask[Math.floor(y-s.bbox.y)*s.bbox.width+Math.floor(x-s.bbox.x)]);if(s){state.selected=state.selected===s.id?null:s.id;updateMetrics();}};
const zone=$('drop-zone');['dragenter','dragover'].forEach(type=>zone.addEventListener(type,e=>{e.preventDefault();zone.classList.add('dragging');}));['dragleave','drop'].forEach(type=>zone.addEventListener(type,e=>{e.preventDefault();zone.classList.remove('dragging');if(type==='drop')loadFile(e.dataTransfer.files[0]);}));
$('sample-switch').onclick=()=>{if(state.busy)return;const values=SAMPLE_COLLECTIONS.map(s=>s.id);useSample(values[(values.indexOf(state.variant)+1)%values.length]);toast('A fresh palette. Same circular possibility.');};
document.querySelectorAll('[data-product]').forEach(button=>button.onclick=async()=>{if(state.busy)return;state.product=button.dataset.product;document.querySelectorAll('[data-product]').forEach(b=>b.classList.toggle('selected',b===button));await replan();studio.playAssembly();});
document.querySelectorAll('[data-objective]').forEach(b=>b.onclick=async()=>{if(state.busy)return;state.objective=b.dataset.objective;document.querySelectorAll('[data-objective]').forEach(x=>x.classList.toggle('selected',x===b));await replan();});
let seamTimer;$('seam-allowance').oninput=e=>{state.seam=Number(e.target.value);$('seam-value').textContent=`${state.seam.toFixed(1)} cm`;clearTimeout(seamTimer);seamTimer=setTimeout(replan,180);};
$('assemble-btn').onclick=()=>{if(!state.plan?.pieces?.length)return toast('Analyze a photo to watch your pieces come together.');$('explode-btn').setAttribute('aria-pressed','false');if(!studio.playAssembly())toast('Assembly animation is off when reduced motion is requested.');};$('explode-btn').onclick=()=>{const b=$('explode-btn');const value=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(value));studio.setExploded(value);};$('wireframe-btn').onclick=()=>{const b=$('wireframe-btn');const value=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(value));studio.setWireframe(value);};$('reset-view').onclick=()=>{studio.resetView();$('explode-btn').setAttribute('aria-pressed','false');$('wireframe-btn').setAttribute('aria-pressed','false');studio.setExploded(false);studio.setWireframe(false);};
function selectView(view){state.view=view;['studio','plan'].forEach(v=>{const b=$('tab-'+v);b.classList.toggle('active',view===v);b.setAttribute('aria-selected',String(view===v));});$('plan-view').hidden=view!=='plan';if(view==='plan')renderPlan();}
$('tab-studio').onclick=()=>selectView('studio');$('tab-plan').onclick=()=>{if(!state.plan)return toast('Analyze your photo to see the cutting plan.');selectView('plan');};$('nav-studio').onclick=()=>{selectView('studio');window.scrollTo({top:0,behavior:'smooth'});};
function showProcess(){modal('A second life starts with a photo.',`<p>ReThread turns an image into a material inventory, then uses that geometry to design around what you already have.</p><div class="process-step"><span>01</span><div><h3>Find the fabric</h3><p>Unsupervised k-means fits colour clusters in perceptual CIELAB space. A border-derived background model separates material from the surface; morphology and connected components trace each scrap, and small enclosed background-coloured motifs (light dots, gingham squares) are kept as fabric. Optional SlimSAM, a pretrained Segment Anything model, reviews a selected boundary locally and can only tighten it.</p></div></div><div class="process-step"><span>02</span><div><h3>Read the cloth with FabricNet</h3><p>A small convolutional network we trained from scratch on synthetic textile patches classifies each scrap as solid, textured, stripe, check, dots or print. A projection-profile (Radon) search measures the pattern’s angle; otherwise the straight cut edges give the grain. Stripes lock cut rotation, and fabric more than 7° off grain is used last.</p></div></div><div class="process-step"><span>03</span><div><h3>Solve the cutting puzzle</h3><p>The solver searches patch grids and rotations, then validates every cut against the material mask and other cuts. Seam allowance is included. Azure can run a deeper seeded search, plan follow-on projects from the exact leftovers, pool fabric across donors, and colour-arrange interchangeable patches.</p></div></div><div class="process-step"><span>04</span><div><h3>See it, then make it</h3><p>Watch the actual cuts lift off your photo and sew themselves into the 3D product. Export a calibrated SVG, an auditable JSON report, or a printable PDF maker packet, and share a read-only link. Review the physical fabric, grain, dimensions and seams before cutting.</p></div></div><p><strong>Local by design.</strong> Analysis and both neural networks run in browser workers. No photo is uploaded; cloud routes receive derived masks and settings only. FabricNet recognises visual pattern, not fibre content or durability.</p><p>Built for Banana Hacks by <strong>Oddment Guild</strong> — Siddhanth K Jain, Adithya P, Kamma Rohan, Dinesh Kulkarni. <a href="https://github.com/Siddhanthkjain2005/Banana_Hacks" target="_blank" rel="noopener">Explore the source ↗</a></p>`);}
['tab-process','nav-guide','learn-more'].forEach(id=>$(id).onclick=showProcess);
$('scale-help').onclick=()=>modal('Give your photo a real-world scale.',`<p>Measure the width of the entire scene, from the left edge of the photo to the right edge, in centimeters. Enter it in <strong>Photo width</strong> before analyzing.</p><h3>For the best result</h3><p>Place every scrap flat on a plain, contrasting surface. Leave space between pieces and around the image edge. Photograph directly from above. Include a ruler for your own scale check.</p><p>Measurements are estimates based on that width. Perspective, folded material and hidden holes can change what is physically cuttable. Inspect the traced edges before using the exported sheet.</p>`, 'MEASURE BEFORE YOU MAKE');
function download(filename,content,type){const url=typeof content==='string'&&content.startsWith('data:')?content:URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();if(!url.startsWith('data:'))setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportCuts(){if(!state.plan||!state.analysis)return toast('Analyze your fabric photo before exporting.');try{download(`rethread-${state.product}-${state.plan.feasible?'cutting-plan':'INCOMPLETE'}.svg`,exportCuttingSVG(state.plan,state.analysis.scraps),'image/svg+xml');toast(state.plan.feasible?'Cutting sheet downloaded. Print at 100% and check the scale bar.':'Partial cutting sheet downloaded. It cannot make the complete product.');}catch(e){toast(e.message);}}
$('export-cut-btn').onclick=exportCuts;$('export-main').onclick=()=>{if(!state.plan)return toast('Analyze your fabric photo before exporting.');modal('Take your next chapter with you.',`<p>Your calibrated pattern and image-derived measurements, ready to review.</p><div class="export-options"><button id="download-svg">${icon('scan')}<span><strong>Cutting sheet · SVG</strong><small>Cut lines, stitch lines, labels and a 10 cm scale bar</small></span></button><button id="download-json">${icon('book')}<span><strong>Material & geometry report · JSON</strong><small>Pixel-derived measurements, assignments and limitations</small></span></button><button id="download-guide">${icon('book')}<span><strong>Sewing guide · TXT</strong><small>Panel order, supplies, assembly steps and scale checks</small></span></button><button id="download-preview">${icon('camera')}<span><strong>3D concept · PNG</strong><small>Your current view of the design studio</small></span></button></div><p>${state.plan.feasible?'The geometry passes containment and overlap checks. Review fabric condition before cutting.':'This is an incomplete layout. Exports clearly label the unplaced cuts.'}</p>`,'MADE TO MAKE');$('download-svg').onclick=exportCuts;$('download-json').onclick=()=>{download('rethread-material-report.json',exportPlanJSON(state.plan,state.analysis),'application/json');toast('Your material report has been downloaded.');};$('download-guide').onclick=()=>{download('rethread-'+state.product+'-sewing-guide.txt',`RETHREAD — ${state.plan.title}\nOddment Guild\n\n${state.plan.feasible?'Complete geometric layout':'INCOMPLETE — a complete plan has not been found'}\nFinished size: ${state.plan.dimensions.widthCm} × ${state.plan.dimensions.heightCm} cm\nSeam allowance: ${state.plan.seamAllowanceCm} cm (included in cuts)\n\nSUPPLIES\n${state.plan.supplies.join('\n')}\n\nASSEMBLY\n${state.plan.assembly.map((s,i)=>(i+1)+'. '+s).join('\n\n')}\n\nCUT INVENTORY\n${state.plan.pieces.map(p=>p.id+' · '+p.widthCm.toFixed(1)+' × '+p.heightCm.toFixed(1)+' cm · '+p.scrapId+(p.rotated?' · rotated':'')).join('\n')}`,'text/plain');toast('Sewing guide downloaded. Start with a paper mock-up.');};$('download-preview').onclick=()=>{const data=studio.capture();if(data){download('rethread-'+state.product+'-concept.png',data,'image/png');toast('Your 3D concept has been downloaded.');}else toast('3D capture is unavailable on this device.');};};
function readCollections(){try{return JSON.parse(localStorage.getItem('rethread-collections')||'[]');}catch{return [];}}
function countCollections(){$('collection-count').textContent=readCollections().length;}
$('save-project').onclick=()=>{if(!state.photo)return;try{const c=document.createElement('canvas');c.width=Math.min(900,state.photo.width);c.height=Math.round(state.photo.height*c.width/state.photo.width);c.getContext('2d').drawImage(state.photo,0,0,c.width,c.height);const collection={id:Date.now(),title:state.sample?`The ${state.variant} collection`:state.filename.replace(/\.[^.]+$/,''),photo:c.toDataURL('image/jpeg',.8),product:state.product,objective:state.objective,seam:state.seam,sceneWidth:Number($('scene-width').value),sample:state.sample,variant:state.variant,date:new Date().toLocaleDateString('en-IN')};const items=readCollections();items.unshift(collection);localStorage.setItem('rethread-collections',JSON.stringify(items.slice(0,5)));$('project-title').textContent=collection.title;countCollections();toast('Collection saved on this device.');}catch{toast('Your browser storage is full. Export the report to keep your work.');}};
$('nav-collections').onclick=()=>{const items=readCollections();modal('Your little library of possibility.',items.length?'<p>Saved locally on this browser. Open a collection to reanalyze its photo.</p>'+items.map(c=>`<div class="collection-card"><img src="${c.photo}" alt="Saved material collection"><div><h3>${escape(c.title)}</h3><p>${escape(c.date)} · ${escape(c.product)} · ${c.sceneWidth} cm scene</p></div><button data-open="${c.id}">Open ↗</button><button data-delete="${c.id}" aria-label="Delete ${escape(c.title)}">${icon('close')}</button></div>`).join(''):'<p>Your saved collections will appear here. Use <strong>Save collection</strong> to keep a photo and its design settings on this device.</p>','YOUR COLLECTIONS');$('dialog-content').querySelectorAll('[data-open]').forEach(b=>b.onclick=async()=>{if(state.busy)return;const c=items.find(c=>c.id===Number(b.dataset.open));const image=new Image();image.src=c.photo;await image.decode();const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;canvas.getContext('2d').drawImage(image,0,0);state.product=c.product;state.objective=c.objective||'color';document.querySelectorAll('[data-objective]').forEach(b=>b.classList.toggle('selected',b.dataset.objective===state.objective));state.seam=c.seam;$('seam-allowance').value=c.seam;$('seam-value').textContent=c.seam.toFixed(1)+' cm';document.querySelectorAll('[data-product]').forEach(x=>x.classList.toggle('selected',x.dataset.product===c.product));setPhoto(canvas,{name:c.title,sample:c.sample,variant:c.variant,sceneWidth:c.sceneWidth});$('project-title').textContent=c.title;$('info-dialog').close();await analyze(true);});$('dialog-content').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{localStorage.setItem('rethread-collections',JSON.stringify(readCollections().filter(c=>c.id!==Number(b.dataset.delete))));countCollections();$('nav-collections').click();});};
$('new-project').onclick=()=>{if(state.busy)return;state.product='tote';state.objective='color';document.querySelectorAll('[data-objective]').forEach(b=>b.classList.toggle('selected',b.dataset.objective==='color'));state.seam=.7;$('seam-allowance').value=.7;$('seam-value').textContent='0.7 cm';document.querySelectorAll('[data-product]').forEach(b=>b.classList.toggle('selected',b.dataset.product==='tote'));$('project-title').textContent='The leftover collection';selectView('studio');useSample('earth');toast('A new collection. Start with your own photo.');};
initNeural({state,$,modal,toast,compute,updateMetrics,replan});
lab=initLab({state,$,modal,toast,compute,studio,updateMetrics,download});
hero=createHero($('hero-stage'));
$('grain-aware').onchange=e=>{state.grainAware=e.target.checked;replan();toast(state.grainAware?'Grain rules on: stripes keep their direction and off-grain fabric is used last.':'Grain rules off: FabricNet results are shown but not used for cutting.');};
const features=initFeatures({state,$,modal,toast,replan,compute,useSample,updateMetrics,buildJobBody:()=>lab.buildJobBody()});
countCollections();useSample('patterns');
if(new URLSearchParams(location.search).has('debug'))window.__rethread={studio,state};
window.addEventListener('beforeunload',()=>{studio.dispose();worker.terminate();});
